55	static void LRC_init(void)
56	{
57	    HAL_RC_CAL_update_reference_cycle_on_48M(LXT_LP_CYCLE);
58	    uint32_t ref_cnt = HAL_RC_CAL_get_reference_cycle_on_48M();
59	    uint32_t cycle_t = (uint32_t)ref_cnt / (48 * LXT_LP_CYCLE);
60	
61	    HAL_PMU_SET_HXT3_RDY_DELAY((HXT_DELAY_EXP_VAL / cycle_t + 1));
62	}
