65	/* void HAL_PreInit(void) */
66	void BSP_Board_PreInit(void)
67	{
68	#ifdef SOC_BF0_HCPU
69	
70	    //MODIFY_REG(hwp_hpsys_rcc->CFGR, HPSYS_RCC_CFGR_PDIV2_Msk,
71	    //           MAKE_REG_VAL(5, HPSYS_RCC_CFGR_PDIV2_Msk, HPSYS_RCC_CFGR_PDIV2_Pos));
72	
73	    // To avoid somebody cancel request.
74	    HAL_HPAON_EnableXT48();
75	
76	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
77	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_HP_PERI, RCC_CLK_PERI_HXT48);
78	
79	    if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
80	    {
81	        // Halt LCPU first to avoid LCPU in running state
82	        HAL_HPAON_WakeCore(CORE_ID_LCPU);
83	        HAL_RCC_Reset_and_Halt_LCPU(1);
84	
85	#ifndef USE_ATE_MODE
86	        // get system/user configure from FLASH OTP
87	        BSP_System_Config();
88	#endif
89	
90	        HAL_PMU_EnableDLL(1);
91	
92	        HAL_PMU_SWITCH_VRET_LOWER();
93	
94	        HAL_HPAON_StartGTimer();
95	#ifndef CFG_BOOTLOADER
96	#ifdef LXT_DISABLE
97	        HAL_PMU_LpCLockSelect(PMU_LPCLK_RC10);
98	#else
99	        HAL_PMU_LpCLockSelect(PMU_LPCLK_XT32);
100	#endif
101	#endif /* CFG_BOOTLOADER */
102	        HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_LP_PERI, RCC_CLK_PERI_HXT48);
103	
104	        HAL_LPAON_EnableXT48();
105	        HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
106	        //  HAL_RCC_LCPU_SetDiv(1, 1, 3);
107	        HAL_RCC_LCPU_SetDiv(1, 1, 3);
108	        if (HAL_PMU_LXT_DISABLED())
109	            LRC_init();
110	    }
111	
112	    __HAL_SYSCFG_HPBG_EN();
113	    __HAL_SYSCFG_HPBG_VDDPSW_EN();
114	
115	    HAL_RCC_HCPU_EnableDLL1(240000000);
116	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_DLL1);
117	
118	    // Reset sysclk used by HAL_Delay_us
119	    HAL_Delay_us(0);
120	
121	    mpi1_div = 1;
122	    mpi2_div = 1;
123	    mpi3_div = 3;
124	    mpi4_div = 3;
125	    mpi5_div = 1;
126	
127	    /* Init the low level hardware */
128	    HAL_MspInit();
129	
130	    if (mpi3_div <= 4)
131	    {
132	        HAL_QSPI_SET_RXDELAY(2, 1, 0);
133	    }
134	    HAL_RCC_HCPU_EnableDLL2(288000000);
135	    HAL_RCC_HCPU_EnableDLL3(216000000);
136	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH3, RCC_CLK_FLASH_DLL3);
137	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH4, RCC_CLK_FLASH_DLL3);
138	#ifdef BSP_USING_PSRAM
139	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_DLL2);
140	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH2, RCC_CLK_FLASH_DLL2);
141	    bsp_psramc_init();
142	#endif
143	
144	#ifdef BSP_USING_NOR_FLASH4
145	    if (PM_STANDBY_BOOT == SystemPowerOnModeGet())
146	    {
147	        BSP_Flash_Init();
148	    }
149	    else
150	    {
151	#ifdef BSP_USING_RTTHREAD
152	        rt_hw_flash_init();
153	#else
154	        BSP_Flash_Init();
155	#endif
156	    }
157	#endif
158	
159	    HAL_RCC_HCPU_SetDiv(1, 2, 5);
160	
161	    HAL_RCC_HCPU_DeepWFIClockSelect(true, RCC_SYSCLK_HXT48);
162	    HAL_RCC_HCPU_SetDeepWFIDiv(48, 0, 1);
163	
164	#ifdef PMIC_CTRL_ENABLE
165	    BSP_PMIC_Init();
166	#endif
167	
168	#ifdef BSP_USING_SDIO
169	    extern void BSP_SD_PowerUp(void);
170	    BSP_SD_PowerUp();
171	
172	    HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SDMMC, RCC_CLK_FLASH_DLL2);
173	    HAL_RCC_HCPU_enable2(HPSYS_RCC_ENR2_SDMMC1, 1);
174	#endif
175	
176	#elif defined(SOC_BF0_LCPU)
177	    HAL_LPAON_EnableXT48();
178	
179	    HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
180	    HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_LP_PERI, RCC_CLK_PERI_HXT48);
181	
182	    mpi5_div = 1;
183	
184	    HAL_RCC_LCPU_SetDiv(1, 1, 3);
185	    if (HAL_PMU_LXT_DISABLED() && PM_STANDBY_BOOT != SystemPowerOnModeGet())
186	    {
187	        HAL_RC_CAL_update_reference_cycle_on_48M(LXT_LP_CYCLE);
188	    }
189	
190	    HAL_MspInit();
191	
192	#endif
193	}
