154	static int sf32lb58_tfcard_mount(void)
155	{
156	#ifndef CONFIG_DISABLE_MOUNTPOINT
157	  static const char *const devpaths[] =
158	  {
159	    "/dev/mmcsd0p0",
160	    "/dev/mmcsd0"
161	  };
162	  int tmpret;
163	  int ret = -ENODEV;
164	  size_t i;
165	
166	  tmpret = mkdir(SF32LB58_TFCARD_MOUNTPOINT, 0755);
167	  if (tmpret < 0 && errno != EEXIST)
168	    {
169	      serr("WARN: mkdir %s failed: %d\n", SF32LB58_TFCARD_MOUNTPOINT, errno);
170	      return -errno;
171	    }
172	
173	  for (i = 0; i < sizeof(devpaths) / sizeof(devpaths[0]); i++)
174	    {
175	      ret = nx_mount(devpaths[i], SF32LB58_TFCARD_MOUNTPOINT, "vfat", 0, NULL);
176	      if (ret >= 0 || ret == -EBUSY)
177	        {
178	          syslog(LOG_INFO, "INFO: TF mounted from %s to %s\n",
179	                 devpaths[i], SF32LB58_TFCARD_MOUNTPOINT);
180	          return OK;
181	        }
182	    }
183	
184	  return ret;
185	#else
186	  return -ENOSYS;
187	#endif
188	}
