190	static int sf32lb58_tfcard_initialize(void)
191	{
192	  FAR struct spi_dev_s *spi;
193	  int ret;
194	
195	  spi = sf32lb58_spi1_getbus();
196	  if (spi == NULL)
197	    {
198	      serr("ERROR: sifli_spibus_initialize(%d) failed\n",
199	           SF32LB58_TFCARD_SPI_PORT);
200	      return -ENODEV;
201	    }
202	
203	  ret = mmcsd_spislotinitialize(SF32LB58_TFCARD_MINOR,
204	                                SF32LB58_TFCARD_SLOT,
205	                                spi);
206	  if (ret < 0)
207	    {
208	      serr("ERROR: mmcsd_spislotinitialize failed: %d\n", ret);
209	      return ret;
210	    }
211	
212	  ret = sf32lb58_tfcard_mount();
213	  if (ret < 0)
214	    {
215	      serr("WARN: TF mount failed: %d\n", ret);
216	    }
217	
218	  return ret;
219	}
220	#endif
