246	/****************************************************************************
247	 * Name: sf32lb58_lcd_bringup
248	 *
249	 * Description:
250	 *   Perform architecture-specific initialization
251	 *
252	 *   CONFIG_BOARD_LATE_INITIALIZE=y
253	 *     Called from board_late_initialize().
254	 *
255	 *   CONFIG_BOARD_LATE_INITIALIZE=n && CONFIG_BOARDCTL=y
256	 *     Called from the NSH library
257	 *
258	 ****************************************************************************/
259	
260	int sf32lb58_lcd_bringup(void)
261	{
262	  int ret = OK;
263	  int tmpret;
264	
265	#ifdef CONFIG_FS_PROCFS
266	  tmpret = mkdir("/proc", 0755);
267	  if (tmpret < 0 && errno != EEXIST)
268	    {
269	      serr("WARN: mkdir /proc failed: %d\n", errno);
270	    }
271	
272	  tmpret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
273	  if (tmpret < 0 && tmpret != -EBUSY)
274	    {
275	      serr("WARN: mount procfs failed: %d\n", tmpret);
276	    }
277	#endif
278	
279	  tmpret = mkdir("/data", 0755);
280	  if (tmpret < 0 && errno != EEXIST)
281	    {
282	      serr("WARN: mkdir /data failed: %d\n", errno);
283	    }
284	
285	#ifdef CONFIG_FS_TMPFS
286	  /* Keep /data writable for syscall and file API test cases. */
287	  tmpret = nx_mount(NULL, "/data", "tmpfs", 0, NULL);
288	  if (tmpret < 0 && tmpret != -EBUSY)
289	    {
290	      serr("WARN: mount tmpfs on /data failed: %d\n", tmpret);
291	    }
292	#endif
293	
294	#if defined(CONFIG_RTC) && defined(CONFIG_RTC_DRIVER)
295	  struct rtc_lowerhalf_s *rtclower = NULL;
296	
297	  rtclower = sf32lb_rtc_lowerhalf();
298	  if (rtclower == NULL)
299	    {
300	      serr("ERROR: Failed to instantiate RTC lower-half\n");
301	      return -ENOMEM;
302	    }
303	
304	  ret = rtc_initialize(0, rtclower);
305	  if (ret < 0)
306	    {
307	      serr("ERROR: rtc_initialize failed: %d\n", ret);
308	      return ret;
309	    }
310	#endif
311	
312	#ifdef CONFIG_ADC
313	  ret = sf32lb_adc_init("/dev/adc0");
314	  if (ret < 0)
315	    {
316	      serr("ERROR: sf32lb_adc_init failed: %d\n", ret);
317	      return ret;
318	    }
319	#endif
320	
321	#ifdef CONFIG_DEV_GPIO
322	  ret = sifli_gpio_initialize();
323	  if (ret < 0)
324	    {
325	      syslog(LOG_ERR, "ERROR: sifli_gpio_initialize failed: %d\n", ret);
326	      return ret;
327	    }
328	#endif
329	
330	#ifdef CONFIG_TIMER
331	#if SF32LB_TIMER_DEFAULT_INDEX >= 0
332	  {
333	    FAR struct timer_lowerhalf_s *timer_lower;
334	    FAR void *timer_upper;
335	
336	    timer_lower = sf32lb_timer_initialize(SF32LB_TIMER_DEFAULT_INDEX,
337	                                          1000000);
338	    if (timer_lower == NULL)
339	      {
340	        syslog(LOG_ERR, "ERROR: sf32lb_timer_initialize failed\n");
341	        return -ENODEV;
342	      }
343	
344	    timer_upper = timer_register("/dev/timer0", timer_lower);
345	    if (timer_upper == NULL)
346	      {
347	        ret = -errno;
348	        syslog(LOG_ERR, "ERROR: timer_register(/dev/timer0) failed: %d\n",
349	               errno);
350	        return ret;
351	      }
352	  }
353	#endif
354	#endif
355	
356	#ifdef CONFIG_PWM
357	#if SF32LB_PWM_DEFAULT_INDEX >= 0
358	  {
359	    FAR struct pwm_lowerhalf_s *pwm_lower;
360	
361	    pwm_lower = sf32lb_pwm_initialize(SF32LB_PWM_DEFAULT_INDEX);
362	    if (pwm_lower == NULL)
363	      {
364	        syslog(LOG_ERR, "ERROR: sf32lb_pwm_initialize failed\n");
365	        return -ENODEV;
366	      }
367	
368	    ret = pwm_register("/dev/pwm0", pwm_lower);
369	    if (ret < 0 && ret != -EEXIST)
370	      {
371	        syslog(LOG_ERR, "ERROR: pwm_register(/dev/pwm0) failed: %d\n", ret);
372	        return ret;
373	      }
374	  }
375	#endif
376	#endif
377	
378	#ifdef CONFIG_INPUT_BUTTONS
379	  ret = sf32lb58_button_initialize("/dev/buttons");
380	  if (ret < 0 && ret != -EEXIST)
381	    {
382	      syslog(LOG_ERR, "ERROR: sf32lb58_button_initialize() failed: %d\n",
383	             ret);
384	      return ret;
385	    }
386	#endif
387	
388	#ifdef CONFIG_I2C
389	  /* Initialize I2C bus 0 on the touch panel pins. */
390	  struct i2c_master_s *i2c0 = NULL;
391	
392	  HAL_PIN_Set(PAD_PA30, I2C1_SCL, PIN_PULLUP, 1);
393	  HAL_PIN_Set(PAD_PA33, I2C1_SDA, PIN_PULLUP, 1);
394	
395	  i2c0 = sifli_i2cbus_initialize(0);
396	  if (i2c0 == NULL)
397	    {
398	      syslog(LOG_ERR, "ERROR: sifli_i2cbus_initialize(0) failed\n");
399	      return -ENODEV;
400	    }
401	
402	  ret = i2c_register(i2c0, 0);
403	  if (ret < 0)
404	    {
405	      syslog(LOG_ERR, "ERROR: i2c_register(/dev/i2c0) failed: %d\n", ret);
406	      return ret;
407	    }
408	
409	#ifdef CONFIG_INPUT_FT6146
410	  ret = ft6146_touch_initialize(i2c0, GET_PIN_2(hwp_gpio1, CONFIG_TOUCH_IRQ_PIN));
411	  if (ret < 0)
412	    {
413	      syslog(LOG_ERR,
414	             "ERROR: ft6146_touch_initialize failed: %d, continue bringup\n",
415	             ret);
416	    }
417	#endif
418	
419	#endif  
420	
421	#if defined(CONFIG_SPI) && defined(CONFIG_BSP_USING_SPI1) && \
422	    defined(CONFIG_SPI_DRIVER)
423	  tmpret = sf32lb58_spi1_register_char();
424	  if (tmpret < 0)
425	    {
426	      serr("WARN: SPI1 char device register failed: %d\n", tmpret);
427	    }
428	#endif
429	
430	#if defined(CONFIG_SPI) && defined(CONFIG_MMCSD_SPI) && \
431	    defined(CONFIG_BSP_USING_SPI1)
432	  tmpret = sf32lb58_tfcard_initialize();
433	  if (tmpret < 0)
434	    {
435	      serr("WARN: TF card init failed: %d\n", tmpret);
436	    }
437	#endif
438	
439	#ifdef CONFIG_LCD
440	  int pid;
