24	/* SF32LB58 memory layout:
25	 *   Flash:  XIP from QSPI1, application starts at 0x12010000
26	 *   SRAM:   RAM0-RAM5 = 2 MB (0x20000000 - 0x20200000)
27	 *   PSRAM:  MPI1 SBUS = 8 MB (0x60000000, configurable)
28	 */
29	
30	MEMORY
31	{
32	  flash (rx) : ORIGIN = 0x12010000, LENGTH = 16M
33	  sram (rwx) : ORIGIN = 0x20000000, LENGTH = 2048K
34	  psram (rwx) : ORIGIN = 0x60000000, LENGTH = 8M
35	}
36	
37	OUTPUT_ARCH(arm)
38	EXTERN(_vectors)
39	/* Provide __Vectors alias for SystemInit() compatibility */
40	__Vectors = _vectors;
41	ENTRY(_stext)
42	
43	SECTIONS
44	{
45	    /* Discard build-id to ensure vectors start at flash base */
46	    /DISCARD/ : {
47	        *(.note.gnu.build-id)
48	    }
49	
50	    .text : {
51	        _stext = ABSOLUTE(.);
52	        /* Ensure vector table is properly aligned (must be at flash start) */
53	        . = ALIGN(512);
54	        KEEP(*(.vectors))
55	        /* Add padding after vectors to match SDK layout */
56	        . = ALIGN(4);
57	        *(.text .text.*)
58	        *(.fixup)
59	        *(.gnu.warning)
60	        *(.rodata .rodata.*)
61	        *(.gnu.linkonce.t.*)
62	        *(.glue_7)
63	        *(.glue_7t)
64	        *(.got)
65	        *(.gcc_except_table)
66	        *(.gnu.linkonce.r.*)
67	
68	        KEEP(*(.init))
69	        KEEP(*(.fini))
70	
71	        /* Section information for finsh shell */
72	        . = ALIGN(4);
73	        __fsymtab_start = .;
74	        KEEP(*(FSymTab))
75	        __fsymtab_end = .;
76	
77	        . = ALIGN(4);
78	        __vsymtab_start = .;
79	        KEEP(*(VSymTab))
80	        __vsymtab_end = .;
81	
82	        . = ALIGN(4);
83	        __rt_utest_tc_tab_start = .;
84	        KEEP(*(UtestTcTab))
85	        __rt_utest_tc_tab_end = .;
86	
87	        /* Section information for initial */
88	        . = ALIGN(4);
89	        __rt_init_start = .;
90	        KEEP(*(SORT(.rti_fn*)))
91	        __rt_init_end = .;
92	
93	        . = ALIGN(4);
94	        __sifli_reg_start__ = .;
95	        KEEP(*(SORT(.sifli_reg*)))
96	        __sifli_reg_end__ = .;
97	
98	        . = ALIGN(4);
99	        __bt_sifli_reg_start__ = .;
100	        KEEP(*(SORT(.bt_sifli_reg*)))
101	        __bt_sifli_reg_end__ = .;
102	
103	        /* Section information for modules */
104	        . = ALIGN(4);
105	        __rtmsymtab_start = .;
106	        KEEP(*(RTMSymTab))
107	        __rtmsymtab_end = .;
108	
109	        /* Section information for LCD drivers */
110	        . = ALIGN(4);
111	        LcdDriverDescTab_start = .;
112	        KEEP(*(LcdDriverDescTab))
113	        LcdDriverDescTab_end = .;
114	
115	        KEEP(*(.eh_frame*))
116	        _etext = ABSOLUTE(.);
117	    } > flash
118	
119	    .ARM.extab : {
120	        *(.ARM.extab*)
121	    } > flash
122	
123	    __exidx_start = ABSOLUTE(.);
124	    .ARM.exidx : {
125	        *(.ARM.exidx*)
126	    } > flash
127	    __exidx_end = ABSOLUTE(.);
128	
129	    .copy.table : {
130	        . = ALIGN(4);
131	        __copy_table_start__ = .;
132	        LONG (LOADADDR(.data))
133	        LONG (ADDR(.data))
134	        LONG (SIZEOF(.data))
135	        __copy_table_end__ = .;
136	    } > flash
137	
138	    .zero.table : {
139	        . = ALIGN(4);
140	        __zero_table_start__ = .;
141	        LONG (__bss_start__)
142	        LONG (__bss_end__ - __bss_start__)
143	        __zero_table_end__ = .;
144	    } > flash
145	
146	    .tdata : {
147	        _stdata = ABSOLUTE(.);
148	        *(.tdata .tdata.* .gnu.linkonce.td.*);
149	        _etdata = ABSOLUTE(.);
150	    } > flash
151	
152	    .tbss : {
153	        _stbss = ABSOLUTE(.);
154	        *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
155	        _etbss = ABSOLUTE(.);
156	    } > flash
157	
158	    _eronly = ABSOLUTE(.);
159	    __etext = ALIGN(4);
160	
161	    /* The RAM vector table (if present) should lie at the beginning of SRAM */
162	
163	    .ram_vectors : {
164	        *(.ram_vectors)
165	    } > sram
166	
167	    .data : {
168	        _sdata = ABSOLUTE(.);
169	        __data_start__ = .;
170	        *(vtable)
171	        *(.data)
172	        *(.data.*)
173	        *(.gnu.linkonce.d.*)
174	        CONSTRUCTORS
175	
176	        . = ALIGN(4);
177	        /* preinit data */
178	        PROVIDE_HIDDEN (__preinit_array_start = .);
179	        KEEP(*(.preinit_array))
180	        PROVIDE_HIDDEN (__preinit_array_end = .);
181	
182	        . = ALIGN(4);
183	        /* init data */
184	        _sinit = ABSOLUTE(.);
185	        PROVIDE(__ctors_start__ = .);
186	        PROVIDE_HIDDEN (__init_array_start = .);
187	        KEEP(*(SORT(.ctors.*)))
188	        KEEP(*(.ctors))
189	        KEEP(*(SORT(.init_array.*)))
190	        KEEP(*(.init_array))
191	        _einit = ABSOLUTE(.);
192	        PROVIDE_HIDDEN (__init_array_end = .);
193	        PROVIDE(__ctors_end__ = .);
194	
195	        . = ALIGN(4);
196	        /* fini data */
197	        PROVIDE(__dtors_start__ = .);
198	        PROVIDE_HIDDEN (__fini_array_start = .);
199	        KEEP(*(SORT(.dtors.*)))
200	        KEEP(*(.dtors))
201	        KEEP(*(SORT(.fini_array.*)))
202	        KEEP(*(.fini_array))
203	        PROVIDE_HIDDEN (__fini_array_end = .);
204	        PROVIDE(__dtors_end__ = .);
205	
206	        KEEP(*(.jcr*))
207	        . = ALIGN(4);
208	        __data_end__ = .;
209	        _edata = ABSOLUTE(.);
210	    } > sram AT > flash
211	
212	    .ramfunc : {
213	        . = ALIGN(4);
214	        _sramfunc = ABSOLUTE(.);
215	        *(.ramfunc .ramfunc.*)
216	        . = ALIGN(4);
217	        _eramfunc = ABSOLUTE(.);
218	    } > sram AT > flash
219	
220	    _siramfunc = LOADADDR(.ramfunc);
221	
222	    .bss : {
223	        . = ALIGN(4);
224	        _sbss = ABSOLUTE(.);
225	        __bss_start__ = .;
226	        *(.bss)
227	        *(.bss.*)
228	        *(.gnu.linkonce.b.*)
229	        *(COMMON)
230	        . = ALIGN(4);
231	        __bss_end__ = .;
232	        _ebss = ABSOLUTE(.);
233	    } > sram
234	
235	    /* Heap starts after BSS */
236	    . = ALIGN(4);
237	    __end__ = .;
238	    PROVIDE(end = .);
239	    PROVIDE(_end = .);
240	
241	    /* Stabs debugging sections. */
242	    .stab 0 : { *(.stab) }
243	    .stabstr 0 : { *(.stabstr) }
244	    .stab.excl 0 : { *(.stab.excl) }
245	    .stab.exclstr 0 : { *(.stab.exclstr) }
246	    .stab.index 0 : { *(.stab.index) }
247	    .stab.indexstr 0 : { *(.stab.indexstr) }
248	    .comment 0 : { *(.comment) }
249	    .debug_abbrev 0 : { *(.debug_abbrev) }
250	    .debug_info 0 : { *(.debug_info) }
251	    .debug_line 0 : { *(.debug_line) }
252	    .debug_pubnames 0 : { *(.debug_pubnames) }
253	    .debug_aranges 0 : { *(.debug_aranges) }
254	}
