 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/* SF32LB58 a128r32n1 memory layout:
 *
 *   Flash (XIP):  QSPI2 NOR at 0x12010000 (app code, 1 MB minus bootloader)
 *   SRAM:         RAM0-RAM5 = 1.5 MB (0x20000000 - 0x20180000)
 *   RET_RAM:      Retention SRAM = 64 KB (0x00020000, survives deep sleep)
 *   ITCM:         Tightly-Coupled Memory = 64 KB (0x00010000)
 *   PSRAM:        MPI1 OPSRAM = 32 MB (0x60000000)
 *
 * Based on SiFli SDK templates/link.lds + templates/mem_map.h.
 */

MEMORY
{
  flash (rx)  : ORIGIN = 0x12010000, LENGTH = 16M
  sram (rwx)  : ORIGIN = 0x20000000, LENGTH = 1536K   /* RAM0-RAM5: 128+128+256+512+512 KB */
  retm (rwx)  : ORIGIN = 0x00020000, LENGTH = 64K     /* Retention RAM, survives deep sleep */
  itcm (rwx)  : ORIGIN = 0x00010000, LENGTH = 64K     /* Instruction Tightly-Coupled Memory */
  psram (rwx) : ORIGIN = 0x60200000, LENGTH = 32M     /* MPI1 OPSRAM, after 2MB code region */
}

OUTPUT_ARCH(arm)
EXTERN(_vectors)
/* Provide __Vectors alias for SystemInit() compatibility */
__Vectors = _vectors;
ENTRY(_stext)

SECTIONS
{
    /* Discard build-id to ensure vectors start at flash base */
    /DISCARD/ : {
        *(.note.gnu.build-id)
    }

    /* ===== Flash (XIP) regions ===== */

    .text : {
        _stext = ABSOLUTE(.);
        /* Ensure vector table is properly aligned (must be at flash start) */
        . = ALIGN(512);
        KEEP(*(.vectors))
        . = ALIGN(4);
        *(.text .text.*)
        *(.fixup)
        *(.gnu.warning)
        *(.rodata .rodata.*)
        *(.gnu.linkonce.t.*)
        *(.glue_7)
        *(.glue_7t)
        *(.got)
        *(.gcc_except_table)
        *(.gnu.linkonce.r.*)

        KEEP(*(.init))
        KEEP(*(.fini))

        /* Section information for finsh shell */
        . = ALIGN(4);
        __fsymtab_start = .;
        KEEP(*(FSymTab))
        __fsymtab_end = .;

        . = ALIGN(4);
        __vsymtab_start = .;
        KEEP(*(VSymTab))
        __vsymtab_end = .;

        . = ALIGN(4);
        __rt_utest_tc_tab_start = .;
        KEEP(*(UtestTcTab))
        __rt_utest_tc_tab_end = .;

        /* Section information for initial */
        . = ALIGN(4);
        __rt_init_start = .;
        KEEP(*(SORT(.rti_fn*)))
        __rt_init_end = .;

        . = ALIGN(4);
        BuiltinApp1Tab_start = .;
        KEEP(*(.BuiltinApp1Tab))
        BuiltinApp1Tab_end = .;

        . = ALIGN(4);
        BuiltinApp2Tab_start = .;
        KEEP(*(.BuiltinApp2Tab))
        BuiltinApp2Tab_end = .;

        . = ALIGN(4);
        __sifli_reg_start__ = .;
        KEEP(*(SORT(.sifli_reg*)))
        __sifli_reg_end__ = .;

        . = ALIGN(4);
        __bt_sifli_reg_start__ = .;
        KEEP(*(SORT(.bt_sifli_reg*)))
        __bt_sifli_reg_end__ = .;

        /* Section information for modules */
        . = ALIGN(4);
        __rtmsymtab_start = .;
        KEEP(*(RTMSymTab))
        __rtmsymtab_end = .;

        /* Section information for LCD drivers */
        . = ALIGN(4);
        LcdDriverDescTab_start = .;
        KEEP(*(LcdDriverDescTab))
        LcdDriverDescTab_end = .;

        . = ALIGN(4);
        __usbh_class_info_start__ = .;
        KEEP(*(.usbh_class_info))
        __usbh_class_info_end__ = .;

        KEEP(*(.eh_frame*))
        _etext = ABSOLUTE(.);
    } > flash

    .ARM.extab : {
        *(.ARM.extab* .gnu.linkonce.armextab.*)
    } > flash

    __exidx_start = ABSOLUTE(.);
    .ARM.exidx : {
        *(.ARM.exidx* .gnu.linkonce.armexidx.*)
    } > flash
    __exidx_end = ABSOLUTE(.);

    /* Copy table for startup — sifli_start.c uses manual copy via linker
     * symbols, but the table is kept for CMSIS/SystemInit compatibility. */

    .copy.table : {
        . = ALIGN(4);
        __copy_table_start__ = .;
        LONG (LOADADDR(.data))
        LONG (ADDR(.data))
        LONG (SIZEOF(.data))

        LONG (LOADADDR(.retm_data))
        LONG (ADDR(.retm_data))
        LONG (SIZEOF(.retm_data))

        LONG (LOADADDR(.itcm_code))
        LONG (ADDR(.itcm_code))
        LONG (SIZEOF(.itcm_code))

        LONG (LOADADDR(.itcm_data))
        LONG (ADDR(.itcm_data))
        LONG (SIZEOF(.itcm_data))
        __copy_table_end__ = .;
    } > flash

    .zero.table : {
        . = ALIGN(4);
        __zero_table_start__ = .;
        LONG (__bss_start__)
        LONG (__bss_end__ - __bss_start__)

        LONG (ADDR(.retm_bss))
        LONG (SIZEOF(.retm_bss))

        LONG (ADDR(.itcm_bss))
        LONG (SIZEOF(.itcm_bss))
        __zero_table_end__ = .;
    } > flash

    .tdata : {
        _stdata = ABSOLUTE(.);
        *(.tdata .tdata.* .gnu.linkonce.td.*);
        _etdata = ABSOLUTE(.);
    } > flash

    .tbss : {
        _stbss = ABSOLUTE(.);
        *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
        _etbss = ABSOLUTE(.);
    } > flash

    _eronly = ABSOLUTE(.);
    __etext = ALIGN(4);

    /* ===== Retention RAM: survives deep sleep, critical boot/periph code ===== */

    .retm_data : {
        . = ALIGN(4);
        __rw_retm_data_start__ = .;

        /* Flash driver & HAL init — must run from RAM for flash reprogramming */
        *(.l1_ret_text_*)
        *(.l1_ret_rodata_*)

        *bsp_init.o         (.text* .rodata*)
        *bsp_lcd_tp.o       (.text* .rodata*)
        *bsp_pinmux.o       (.text* .rodata*)
        *bsp_power.o        (.text* .rodata*)
        *bf0_hal_gpio.o     (.text* .rodata*)
        *bf0_hal_hpaon.o    (.text* .rodata*)
        *bf0_hal.o          (.text.HAL_Init)
        *bf0_hal_pinmux.o   (.text* .rodata*)
        *bf0_pin_const.o    (.text* .rodata*)

        *bf0_hal_mpi.o      (.text* .rodata*)
        *bf0_hal_mpi_ex.o   (.text* .rodata*)
        *bf0_hal_mpi_psram.o (.text* .rodata*)
        *flash.o            (.text* .rodata*)
        *flash_table.o      (.text* .rodata*)
        *drv_psram.o        (.text* .rodata*)

        *context_gcc.o      (.text* .rodata*)
        *drv_common.o       (.text.HAL_GetTick)
        *bf0_hal_rcc.o      (.text* .rodata*)

        *bf0_pm.o           (.text.sifli_light_handler)
        *bf0_pm.o           (.text.sifli_deep_handler)
        *bf0_pm.o           (.text.sifli_standby_handler)
        *bf0_pm.o           (.text.SystemInitFromStandby)
        *.o                 (.text.SystemPowerOnModeGet)
        *.o                 (.text.HAL_Delay_us)
        *.o                 (.text.HAL_Delay_us_)
        *.o                 (.text.HAL_MspInit)

        . = ALIGN(4);
        __nor_cfg_db_start__ = .;
        KEEP(*(.nor_cfg_db))
        __nor_cfg_db_end__ = .;

        . = ALIGN(4);
        __RW_IRAM_RET$$RW_start__ = .;
        *.o (.retm_data_*)
        . = ALIGN(4);
        __RW_IRAM_RET$$RW_end__ = .;
        __rw_retm_data_end__ = .;
    } > retm AT > flash

    /* ===== ITCM: tightly-coupled code for low-latency execution ===== */

    .itcm_code : {
        . = ALIGN(4);
        __rw_itcm_code_start__ = .;
        __ER_ITCM$$RO_start__ = .;
        __ER_ITCM$$RO_load_start__ = LOADADDR(.itcm_code);

        . = ALIGN(4);
        __rw_itcm_code_end__ = .;
        __ER_ITCM$$RO_end__ = .;
        __ER_ITCM$$RO_load_end__ = LOADADDR(.itcm_code) + SIZEOF(.itcm_code);
    } > itcm AT > flash

    .itcm_data : {
        . = ALIGN(4);
        __rw_itcm_data_start__ = .;
        __ER_ITCM$$RW_start__ = .;

        . = ALIGN(4);
        __rw_itcm_data_end__ = .;
        __ER_ITCM$$RW_end__ = .;
    } > itcm AT > flash

    /* ===== SRAM regions ===== */

    /* The RAM vector table (if present) should lie at the beginning of SRAM */
    .ram_vectors : {
        *(.ram_vectors)
    } > sram

    .data : {
        _sdata = ABSOLUTE(.);
        __data_start__ = .;
        *(vtable)
        *(.data)
        *(.data.*)
        *(.gnu.linkonce.d.*)
        *(.l1_ret_data_*)
        CONSTRUCTORS

        . = ALIGN(4);
        /* preinit data */
        PROVIDE_HIDDEN (__preinit_array_start = .);
        KEEP(*(.preinit_array))
        PROVIDE_HIDDEN (__preinit_array_end = .);

        . = ALIGN(4);
        /* init data */
        _sinit = ABSOLUTE(.);
        PROVIDE(__ctors_start__ = .);
        PROVIDE_HIDDEN (__init_array_start = .);
        KEEP(*(SORT(.ctors.*)))
        KEEP(*(.ctors))
        KEEP(*(SORT(.init_array.*)))
        KEEP(*(.init_array))
        _einit = ABSOLUTE(.);
        PROVIDE_HIDDEN (__init_array_end = .);
        PROVIDE(__ctors_end__ = .);

        . = ALIGN(4);
        /* fini data */
        PROVIDE(__dtors_start__ = .);
        PROVIDE_HIDDEN (__fini_array_start = .);
        KEEP(*(SORT(.dtors.*)))
        KEEP(*(.dtors))
        KEEP(*(SORT(.fini_array.*)))
        KEEP(*(.fini_array))
        PROVIDE_HIDDEN (__fini_array_end = .);
        PROVIDE(__dtors_end__ = .);

        KEEP(*(.jcr*))
        . = ALIGN(4);
        __data_end__ = .;
        _edata = ABSOLUTE(.);
    } > sram AT > flash

    .ramfunc : {
        . = ALIGN(4);
        _sramfunc = ABSOLUTE(.);
        *(.ramfunc .ramfunc.*)
        . = ALIGN(4);
        _eramfunc = ABSOLUTE(.);
    } > sram AT > flash

    _siramfunc = LOADADDR(.ramfunc);

    /* Non-retained data in SRAM (if not in PSRAM) */
    .RW_IRAM0 : {
        *(non_ret)
        *(.*l1_non_ret_data_*)
        *(.*l1_non_ret_bss_*)
    } > sram

    .retm_bss : {
        . = ALIGN(4);
        __rw_retm_bss_start__ = .;
        __RW_IRAM_RET$$ZI_start__ = .;
        *(.bss.retm_bss_*)
        *idle.o (.bss.idle_thread_stack)
        *.o(.bss.bf0_psram_handle)
        . = ALIGN(4);
        __RW_IRAM_RET$$ZI_end__ = .;
    } > retm

    .itcm_bss : {
        . = ALIGN(4);
        __rw_itcm_bss_start__ = .;
        __ER_ITCM$$ZI_start__ = .;

        . = ALIGN(4);
        __rw_itcm_bss_end__ = .;
        __ER_ITCM$$ZI_end__ = .;
    } > itcm

    .bss : {
        . = ALIGN(4);
        _sbss = ABSOLUTE(.);
        __bss_start__ = .;
        *(.bss)
        *(.bss.*)
        *(.gnu.linkonce.b.*)
        *(COMMON)
        *(.l1_ret_bss_*)
        . = ALIGN(4);
        __bss_end__ = .;
        _ebss = ABSOLUTE(.);
    } > sram

    /* Heap starts after BSS */
    . = ALIGN(4);
    __end__ = .;
    PROVIDE(end = .);
    PROVIDE(_end = .);

    /* ===== PSRAM: additional heap for large allocations ===== */

    .RW_PSRAM1 : {
        . = ALIGN(4);
        __rw_psram1_start__ = .;
        *(.*l2_ret_data_*)
        *(.*l2_ret_bss_*)
        *(.*l2_cache_ret_data_*)
        *(.*l2_cache_ret_bss_*)
        . = ALIGN(4);
        __rw_psram1_end__ = .;
    } > psram

    .RW_PSRAM_NON_RET : {
        . = ALIGN(32);  /* Cache-line aligned */
        __RW_PSRAM_NON_RET_start__ = .;
        *(.nand_cache)
        *(.*l2_cache_non_ret_data_*)
        *(.*l2_cache_non_ret_bss_*)
        . = ALIGN(4);
        __RW_PSRAM_NON_RET_end__ = .;
    } > psram

    /* Stabs debugging sections. */
    .stab 0 : { *(.stab) }
    .stabstr 0 : { *(.stabstr) }
    .stab.excl 0 : { *(.stab.excl) }
    .stab.exclstr 0 : { *(.stab.exclstr) }
    .stab.index 0 : { *(.stab.index) }
    .stab.indexstr 0 : { *(.stab.indexstr) }
    .comment 0 : { *(.comment) }
    .debug_abbrev 0 : { *(.debug_abbrev) }
    .debug_info 0 : { *(.debug_info) }
    .debug_line 0 : { *(.debug_line) }
    .debug_pubnames 0 : { *(.debug_pubnames) }
    .debug_aranges 0 : { *(.debug_aranges) }
}

